<template><div class="page"><el-card><template #header><span>结算管理</span></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="settlement_no" label="结算单号" width="180"/><el-table-column prop="amount" label="结算金额" width="120"/><el-table-column prop="fee" label="手续费" width="100"/><el-table-column prop="real_amount" label="实到金额" width="120"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===1?'success':'warning'">{{row.status===1?'已结算':'待结算'}}</el-tag></template></el-table-column><el-table-column prop="created_at" label="创建时间" width="170"/></el-table></el-card></div></template><script setup>import{ref,onMounted}from'vue';import request from'@/utils/request';const list=ref([]);onMounted(async()=>{const res=await request({url:'/merchant/finance/settlements'});list.value=res.data?.list||res.data||[]})</script>
